using Microsoft.AspNetCore.Mvc; namespace AiBotApp.Controllers { [ApiController] [Route("api/[controller]")] public class BotController : ControllerBase { [HttpPost("chat")] public async Task<IActionResult> GetResponse([FromBody] ChatRequest request) { if (string.IsNullOrEmpty(request.Message)) { return BadRequest("الرسالة لا يمكن أن تكون فارغة"); } var response = await ProcessAiLogic(request.Message); return Ok(new { Reply = response, Status = "Success" }); } private async Task<string> ProcessAiLogic(string input) { await Task.Delay(500); return $"الرد الاحترافي على: {input}"; } } public class ChatRequest { public string Message { get; set; } } }